@Serializable
data class UserDto(
    val id: Long,
    val name: String,
    val email: String,
    @SerialName("created_at") val createdAt: String,
)

interface UsersApi {
    @GET("users")
    suspend fun all(): List<UserDto>

    @GET("users/{id}")
    suspend fun byId(@Path("id") id: Long): UserDto

    @POST("users")
    suspend fun create(@Body body: CreateUserRequest): UserDto

    @DELETE("users/{id}")
    suspend fun delete(@Path("id") id: Long)
}

@Module @InstallIn(SingletonComponent::class)
object NetworkModule {

    @Provides @Singleton
    fun provideJson(): Json = Json {
        ignoreUnknownKeys = true
        encodeDefaults = true
        explicitNulls = false
    }

    @Provides @Singleton
    fun provideOkHttp(
        authInterceptor: AuthInterceptor,
        headersInterceptor: HeadersInterceptor,
    ): OkHttpClient = OkHttpClient.Builder()
        .connectTimeout(10, TimeUnit.SECONDS)
        .readTimeout(20, TimeUnit.SECONDS)
        .callTimeout(30, TimeUnit.SECONDS)
        .retryOnConnectionFailure(true)
        .addInterceptor(headersInterceptor)
        .addInterceptor(authInterceptor)
        .apply {
            if (BuildConfig.DEBUG) {
                addInterceptor(HttpLoggingInterceptor().apply { level = HttpLoggingInterceptor.Level.BODY })
            }
        }
        .build()

    @Provides @Singleton
    fun provideRetrofit(client: OkHttpClient, json: Json): Retrofit = Retrofit.Builder()
        .baseUrl("https://api.exemplo.com/")
        .client(client)
        .addConverterFactory(json.asConverterFactory("application/json".toMediaType()))
        .build()

    @Provides @Singleton
    fun provideUsersApi(r: Retrofit): UsersApi = r.create(UsersApi::class.java)
}

class AuthInterceptor @Inject constructor(
    private val tokenStore: TokenStore,
) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val original = chain.request()
        val token = tokenStore.access() ?: return chain.proceed(original)

        val withAuth = original.newBuilder()
            .header("Authorization", "Bearer " + token)
            .build()

        val response = chain.proceed(withAuth)

        if (response.code == 401) {
            response.close()
            val newToken = runBlocking { tokenStore.refresh() } ?: return chain.proceed(original)
            val retried = original.newBuilder()
                .header("Authorization", "Bearer " + newToken)
                .build()
            return chain.proceed(retried)
        }
        return response
    }
}

sealed interface ApiError : Throwable {
    data object NoConnection : ApiError
    data class Http(val code: Int, val body: String?) : ApiError
    data class Unexpected(val cause: Throwable) : ApiError
}

suspend inline fun <T> safeCall(crossinline block: suspend () -> T): Result<T> = runCatching {
    block()
}.recoverCatching { t ->
    throw when (t) {
        is IOException -> ApiError.NoConnection
        is HttpException -> ApiError.Http(t.code(), t.response()?.errorBody()?.string())
        else -> ApiError.Unexpected(t)
    }
}

